<script setup>
import { computed } from 'vue'
const props = defineProps({ node: Object, nodes: { type: Array, default: () => [] } })
const emit = defineEmits(['select-node'])
const names = ['图像识别','目标检测','视频分析','语音处理','信号计算'], resources = ['CPU','NPU','FPGA']
const node = computed(() => props.node?.speed ? props.node : props.nodes.find(n => n.kind === 'edge'))
const pct = (v, max) => max ? Math.min(100, 100*v/max) : 0
</script>
<template><div class="resource-panel"><div class="panel-heading"><div><div class="eyebrow">NODE INSPECTOR</div><h3>节点资源</h3></div><el-select v-if="nodes.length" :model-value="node?.id" size="small" style="width:120px" @change="id => emit('select-node',nodes.find(n=>n.id===id))"><el-option v-for="n in nodes" :key="n.id" :label="n.label" :value="n.id" /></el-select></div><div v-if="node"><div class="node-title"><strong>{{ node.label }}</strong><span class="chip">{{ node.profile === 'cloud' ? '云端' : node.profile === 'balanced' ? '轻量中继' : node.profile + ' 强' }}</span></div><div class="minor-label">计算资源 <span>GFLOP/s</span></div><div v-for="(name,i) in resources" :key="name" class="resource-row"><div class="resource-label"><b>{{ name }}</b><span>{{ node.resource_used[i].toFixed(1) }} / {{ node.speed[i].toFixed(1) }}</span></div><div class="bar"><i class="carry" :style="{width:pct(node.carryover_used[i],node.speed[i])+'%'}"></i><i class="new" :style="{width:pct(Math.max(0,node.resource_used[i]-node.carryover_used[i]),node.speed[i])+'%'}"></i></div></div><div class="mini-legend"><span><i class="carry"></i>跨时隙冻结</span><span><i class="new"></i>本时隙新增</span></div><div class="minor-label">资源水位</div><div v-for="r in [['内存',node.mem_used,node.mem_cap,'GB'],['存储',node.storage_used,node.storage_cap,'GB'],['队列',node.queue_used,node.queue_cap,'']]" :key="r[0]" class="water"><span>{{ r[0] }}</span><div class="bar"><i class="new" :style="{width:pct(r[1],r[2])+'%'}"></i></div><small>{{ Number(r[1]).toFixed(1) }} / {{ r[2] }} {{ r[3] }}</small></div><div class="minor-label">已部署服务</div><div class="tags"><span v-for="s in node.services" :key="s" class="service-tag">T{{ s }} {{ names[s] }}</span></div><div class="minor-label">在途任务</div><p class="muted">{{ node.active_task_ids.length ? node.active_task_ids.map(id=>'#'+id).join('、') : '当前无驻留任务' }}</p></div><el-empty v-else description="选择节点查看详情" :image-size="60" /></div></template>
